    def audit(self, *, limit: Optional[int] = None, user: Optional[str] = None) -> List[AuditEvent]:
        """Newest audit events.

        Preview: becomes an admin route with G06.

        `GET /v1/audit`. Stability: preview.

        - `limit`: 1 to 1000 (default 100).
        - `user`: The user the call acts for. Accepted only from admins and from agents trusted to act for users (`act_as`); a user's key always acts for that user, a token for its own user.
        """
        return self._call("GET", "/v1/audit", query={"limit": limit}, headers={"x-memhouse-user": user})

    def files_changed(self, body: FilesChangedRequest, *, user: Optional[str] = None, actor: Optional[str] = None) -> FilesChangedResult:
        """Report files that changed, were deleted or renamed.

        Marks staleness in batch (TPL-04), what a post-commit hook calls: for files the agent never opened too. A changed file carries its new content hash, a deleted one `deleted`, a renamed one `renamed_from` and its hash. A memory with a stale reference is left out of default recall until it is revalidated, revised or forgotten. The answer lists the changes to memories a recall could give the caller now (committed, valid, unexpired); `flagged` and `cleared` count the memories whose staleness this request changed (`was_stale` against `stale`), not the references. References and their audit events are written in one transaction. Needs `memory:write`. Audited as `memory.stale`, `memory.fresh` and `memory.code_moved`.

        `POST /v1/code/changed`. Stability: stable.

        - `user`: The user the call acts for. Accepted only from admins and from agents trusted to act for users (`act_as`); a user's key always acts for that user, a token for its own user.
        - `actor`: (deprecated) Ignored since 1.1: the audit actor and `provenance.agent` are the authenticated principal.
        """
        return self._call("POST", "/v1/code/changed", body=body, headers={"x-memhouse-user": user, "x-memhouse-actor": actor})

    def revalidate(self, body: RevalidateRequest, *, user: Optional[str] = None, actor: Optional[str] = None) -> RevalidateResult:
        """Confirm that a stale memory still holds.

        Revalidation (TPL-04): code references of the memory take a hash the caller vouches for and are no longer stale. With `code_refs`, only the references named take the given hashes (a partial revalidation: `stale` in the answer stays true while another reference is stale, and the memory returns to default recall only when none is); without, every stale reference takes the hash its file was last seen with, which is the checked content only if nothing changed the file since (a reference to a deleted file has none: `400`; revise or forget the memory). A given hash confirms that content only: where the file was since seen with another hash, or reported deleted, the reference takes the given one and stays stale (with the hash seen, if any) until the file is reported with that content; for a reference that is not stale, a given hash other than the stored one is a `409` (the file was last known with the stored content: report the file first). Needs `memory:write` and sight of the memory. Audited as `memory.revalidate`.

        `POST /v1/code/revalidate`. Stability: stable.

        - `user`: The user the call acts for. Accepted only from admins and from agents trusted to act for users (`act_as`); a user's key always acts for that user, a token for its own user.
        - `actor`: (deprecated) Ignored since 1.1: the audit actor and `provenance.agent` are the authenticated principal.
        """
        return self._call("POST", "/v1/code/revalidate", body=body, headers={"x-memhouse-user": user, "x-memhouse-actor": actor})

    def file_touched(self, body: FileTouchedRequest, *, user: Optional[str] = None, actor: Optional[str] = None) -> FileTouchedResult:
        """Memories linked to files an agent opened or edited.

        File-touched recall (TPL-05), what a coding harness's hook calls. Each file comes with its current content hash (the git blob hash by convention). First the staleness of the memories linked to the files is updated (TPL-04): a reference whose stored hash differs becomes stale, one whose file has its stored content again stops being stale, a rename moves it. Then every linked memory the caller may recall is returned, under the same access decision as `recall`: `memories` (not stale) and `needs_revalidation` (stale: left out of default recall until revalidated, revised or forgotten). With `query`, procedures that match the task are added in `related`. Needs `memory:read`; the staleness is recorded only for a caller that also has `memory:write` (for others the comparison is made for the answer alone). Several states of one file are applied in order. Changes are audited as `memory.stale`, `memory.fresh` and `memory.code_moved`; another hash seen on a reference that is stale already is no change of state, and is audited as `memory.code_seen`.

        `POST /v1/code/touched`. Stability: stable.

        - `user`: The user the call acts for. Accepted only from admins and from agents trusted to act for users (`act_as`); a user's key always acts for that user, a token for its own user.
        - `actor`: (deprecated) Ignored since 1.1: the audit actor and `provenance.agent` are the authenticated principal.
        """
        return self._call("POST", "/v1/code/touched", body=body, headers={"x-memhouse-user": user, "x-memhouse-actor": actor})

